<?php
namespace EyeDonation\SiteMigrations;
defined('ABSPATH') || exit;
/** Immutable follow-up; classic nav_menu terms/items and assignments are never touched. */
final class PrimaryNavigationMigration {
 const ID='008_apply_primary_navigation';
 public static function checksum(){return hash('sha256',file_get_contents(__FILE__).file_get_contents(__DIR__.'/008-primary-navigation.json'));}
 public static function content(){
  $build=function($items)use(&$build){$blocks=[];foreach($items as $item){$attrs=['label'=>$item['label'],'kind'=>'custom'];if(isset($item['url'])){$url=$item['url'];$attrs['url']=str_starts_with($url,'/')?home_url($url):$url;} $children=isset($item['children'])?$build($item['children']):[];$blocks[]=['blockName'=>$children?'core/navigation-submenu':'core/navigation-link','attrs'=>$attrs,'innerBlocks'=>$children,'innerHTML'=>'','innerContent'=>array_fill(0,count($children),null)];}return $blocks;};
  return serialize_blocks($build(json_decode(file_get_contents(__DIR__.'/008-primary-navigation.json'),true,512,JSON_THROW_ON_ERROR)));
 }
 public static function plan(){preflight();$id=managed('navigation.primary','wp_navigation');if(!$id)fail('No managed primary block menu exists. Fresh installations use the shipped header defaults; existing sites must complete navigation setup first.');return post_operation('navigation.primary','wp_navigation','ed-primary',self::content());}
 public static function preview(){ $state=history()[self::ID]??[];if(isset($state['checksum'])&&$state['checksum']!==self::checksum())fail('008 checksum changed.');$op=self::plan();$p=['actor'=>get_current_user_id(),'checksum'=>self::checksum(),'operation'=>$op,'created'=>time()];update_option('edm_primary_navigation_preview',$p,false);return $p; }
 public static function run(){preflight();$token=lock_acquire();try{$h=history();$old=$h[self::ID]??[];if(isset($old['checksum'])&&$old['checksum']!==self::checksum())fail('008 checksum changed.');$op=self::plan();if(($old['status']??'')==='completed'){if($op['action']!=='already-satisfied')fail('Completed menu has drifted; prepare a new migration.');return 'Primary menu already completed.';}
  $p=get_option('edm_primary_navigation_preview');if(!$p||$p['actor']!==get_current_user_id()||$p['checksum']!==self::checksum())fail('Fresh preview required.');$expected=$p['operation'];if($expected['id']!==$op['id']||($op['before']!==$expected['before']&&$op['action']!=='already-satisfied'))fail('Menu changed after preview.');
  $h[self::ID]=array_merge($old,['status'=>'running','checksum'=>self::checksum(),'actor'=>get_current_user_id(),'run_id'=>$old['run_id']??wp_generate_uuid4(),'started'=>$old['started']??time(),'destination_id'=>$op['id'],'before'=>$old['before']??$expected['before']]);lock_check($token);save_history($h);apply_operation($op);lock_check($token);if(self::plan()['action']!=='already-satisfied')fail('Menu postcondition failed.');$h[self::ID]['status']='completed';$h[self::ID]['completed']=time();$h[self::ID]['after_fingerprint']=fingerprint($op['after']);save_history($h);return 'Approved primary block menu applied. Classic menus preserved.';
 }finally{lock_release($token);}}
}
foreach(['preview','run'] as $mode)add_action('admin_post_edm_primary_'.$mode,function()use($mode){if(!current_user_can('manage_options'))wp_die('Unauthorized');check_admin_referer('edm_primary_'.$mode);try{if($mode==='run'&&empty($_POST['backup']))fail('Backup acknowledgment required.');$result=$mode==='preview'?PrimaryNavigationMigration::preview():PrimaryNavigationMigration::run();update_option('edm_primary_navigation_notice',is_string($result)?$result:'Preview ready.',false);}catch(\Throwable $e){update_option('edm_primary_navigation_notice',$e->getMessage(),false);}wp_safe_redirect(admin_url('tools.php?page=eyedonation-migrations'));exit;});
add_action('admin_footer',function(){if(($_GET['page']??'')!=='eyedonation-migrations'||!current_user_can('manage_options'))return;$state=history()[PrimaryNavigationMigration::ID]??[];echo '<div class="wrap"><h2>008 — Approved primary block menu</h2><p>Updates only the managed primary block menu. Preserves classic menus, footer, and editor customizations. Status: '.esc_html($state['status']??'pending').'</p><p role="status">'.esc_html(get_option('edm_primary_navigation_notice','')).'</p>';
 foreach(['preview'=>'Preview Changes','run'=>'Process / Resume primary menu'] as $mode=>$label){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="edm_primary_'.$mode.'">';wp_nonce_field('edm_primary_'.$mode);if($mode==='run')echo '<p><label><input type="checkbox" name="backup" value="1" required> I have a current backup.</label></p>';submit_button($label);echo '</form>';}
 $preview=get_option('edm_primary_navigation_preview');if($preview)echo '<details><summary>Preview menu blocks</summary><pre>'.esc_html($preview['operation']['after']).'</pre></details>';echo '</div>';
});
